import React, { useState, useEffect } from "react";
import { useStatus } from "../contexts/StatusContext";
import { useI18n } from "../contexts/I18nContext";
import {
  UsersIcon,
  TasksIcon,
  ClockIcon,
  CpuIcon,
  ArrowUpIcon,
  ArrowDownIcon,
  ErrorIcon,
} from "./Icons";


interface StatCardProps {
  title: string;
  value: string | number;
  change?: string;
  changeType?: "increase" | "decrease" | "neutral";
  icon: React.ReactNode;
  color: "primary" | "success" | "warning" | "error" | "secondary";
}

const StatCard: React.FC<StatCardProps> = ({
  title,
  value,
  change,
  changeType = "neutral",
  icon,
  color,
}) => {
  const colorClasses = {
    primary: "gradient-primary",
    success: "gradient-success",
    warning: "gradient-warning",
    error: "gradient-error",
    secondary: "gradient-secondary",
  };

  const changeColorClasses = {
    increase: "text-success-600 bg-success-50",
    decrease: "text-error-600 bg-error-50",
    neutral: "text-secondary-600 bg-secondary-50",
  };

  return (
    <div className="bg-white rounded-xl shadow-sm p-6 card-hover">
      <div className="flex items-center">
        <div className={`p-3 rounded-lg ${colorClasses[color]} text-white`}>
          {icon}
        </div>
        <div className="ml-4 flex-1">
          <p className="text-sm font-medium text-secondary-600 mb-1">{title}</p>
          <p className="text-2xl font-bold text-secondary-900">{value}</p>
          {change && (
            <div
              className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium mt-2 ${changeColorClasses[changeType]}`}
            >
              {changeType === "increase" && (
                <ArrowUpIcon size="sm" className="mr-1" />
              )}
              {changeType === "decrease" && (
                <ArrowDownIcon size="sm" className="mr-1" />
              )}
              {change}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

interface ProgressBarProps {
  label: string;
  value: number;
  max: number;
  color: "primary" | "success" | "warning" | "error";
}

const ProgressBar: React.FC<ProgressBarProps> = ({
  label,
  value,
  max,
  color,
}) => {
  const percentage = Math.min((value / max) * 100, 100);

  const colorClasses = {
    primary: "bg-primary-500",
    success: "bg-success-500",
    warning: "bg-warning-500",
    error: "bg-error-500",
  };

  return (
    <div className="mb-4">
      <div className="flex justify-between text-sm text-secondary-600 mb-1">
        <span>{label}</span>
        <span>
          {value}/{max}
        </span>
      </div>
      <div className="w-full bg-secondary-200 rounded-full h-2">
        <div
          className={`h-2 rounded-full transition-all duration-300 ${colorClasses[color]}`}
          style={{ width: `${percentage}%` }}
        />
      </div>
    </div>
  );
};

interface ClientStatusProps {
  clients: any[];
}

const ClientStatus: React.FC<ClientStatusProps> = ({ clients }) => {
  const { t } = useI18n();
  const statusCounts = clients.reduce((acc, client) => {
    const status = client.connection_status || "disconnected";
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {});

  const statusItems = [
    {
      status: "connected",
      label: t("common.online"),
      color: "success",
      count: statusCounts.connected || 0,
    },
    {
      status: "disconnected",
      label: t("common.offline"),
      color: "error",
      count: statusCounts.disconnected || 0,
    },
    {
      status: "connecting",
      label: t("header.connectionStatus"),
      color: "warning",
      count: statusCounts.connecting || 0,
    },
    {
      status: "error",
      label: t("common.error"),
      color: "error",
      count: statusCounts.error || 0,
    },
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm p-6">
      <h3 className="text-lg font-semibold text-secondary-900 mb-4">
        {t("clients.connectionStatus")}
      </h3>
      <div className="space-y-3">
        {statusItems.map(
          (item) =>
            item.count > 0 && (
              <div
                key={item.status}
                className="flex items-center justify-between"
              >
                <div className="flex items-center">
                  <div
                    className={`w-3 h-3 rounded-full mr-3 ${
                      item.color === "success"
                        ? "status-online"
                        : item.color === "warning"
                          ? "status-warning"
                          : "status-offline"
                    }`}
                  />
                  <span className="text-sm text-secondary-600">
                    {item.label}
                  </span>
                </div>
                <span className="text-sm font-medium text-secondary-900">
                  {item.count}
                </span>
              </div>
            ),
        )}
        {clients.length === 0 && (
          <div className="text-center py-4">
            <p className="text-sm text-secondary-500">{t("clients.noClients")}</p>
          </div>
        )}
      </div>
    </div>
  );
};

// Quick Stats Card Component
interface QuickStatProps {
  title: string;
  value: string | number;
  subtitle?: string;
  icon: string;
  trend?: {
    value: string;
    isPositive: boolean;
  };
  color: "blue" | "green" | "yellow" | "red" | "purple" | "indigo";
}

const QuickStat: React.FC<QuickStatProps> = ({
  title,
  value,
  subtitle,
  icon,
  trend,
  color,
}) => {
  const gradientClasses = {
    blue: "gradient-primary",
    green: "gradient-success",
    yellow: "gradient-warning",
    red: "gradient-error",
    purple: "gradient-secondary",
    indigo: "gradient-info",
  };

  return (
    <div
      className={`bg-white rounded-xl shadow-sm p-6 card-hover border border-secondary-100 dashboard-scale-in`}
    >
      <div className="flex items-center justify-between">
        <div className="flex-1">
          <p className="text-sm font-medium text-secondary-700 mb-2">{title}</p>
          <p className="text-3xl font-bold text-secondary-900">{value}</p>
          {subtitle && (
            <p className="text-xs text-secondary-600 mt-2">{subtitle}</p>
          )}
          {trend && (
            <div
              className={`inline-flex items-center mt-3 px-3 py-1 rounded-full text-xs font-medium ${
                trend.isPositive
                  ? "bg-green-100 text-green-800"
                  : "bg-red-100 text-red-800"
              }`}
            >
              <span className="mr-1">{trend.isPositive ? "↗" : "↘"}</span>
              {trend.value}
            </div>
          )}
        </div>
        <div
          className={`w-16 h-16 rounded-xl ${gradientClasses[color]} flex items-center justify-center text-white text-2xl shadow-md`}
        >
          <span>{icon}</span>
        </div>
      </div>
    </div>
  );
};

// System Health Component
const SystemHealth: React.FC = () => {
  const { state } = useStatus();
  const { t } = useI18n();

  const healthItems = [
    {
      name: "WebSocket Server",
      description: t("dashboard.realtimeCommunication"),
      status: state.connectionStatus === "connected",
    },
    {
      name: "Redis Cache",
      description: t("dashboard.dataCachingLayer"),
      status: state.health?.components?.redis || false,
    },
    {
      name: "Client Manager",
      description: t("dashboard.connectionManagement"),
      status: state.health?.components?.client_manager || false,
    },
    {
      name: "Task Router",
      description: t("dashboard.taskDistribution"),
      status: state.health?.components?.task_router || false,
    },
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6 dashboard-slide-up">
      <h3 className="text-lg font-semibold text-secondary-900 mb-6">
        💻 {t("dashboard.systemHealth")}
      </h3>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {healthItems.map((item, index) => (
          <div
            key={item.name}
            className={`flex items-center justify-between p-4 bg-secondary-50 rounded-lg`}
          >
            <div className="flex-1">
              <p className="text-sm font-medium text-secondary-900">
                {item.name}
              </p>
              <p className="text-xs text-secondary-600">{item.description}</p>
            </div>
            <div
              className={`w-4 h-4 rounded-full ${
                item.status ? "status-online" : "status-offline"
              }`}
            />
          </div>
        ))}
      </div>

      {state.health?.version && (
        <div className="mt-4 pt-4 border-t border-secondary-200">
          <p className="text-xs text-secondary-500">
            {t("dashboard.systemVersion")}:{" "}
            <span className="font-medium">{state.health.version}</span>
          </p>
        </div>
      )}
    </div>
  );
};

// Resource Monitor Component
// ResourceMonitor перенесено до компоненту WorkerMetrics як SystemResourceMonitor

// Live Activity Feed Component
const LiveActivityFeed: React.FC = () => {
  const { state } = useStatus();
  const { t } = useI18n();

  return (
    <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6 dashboard-slide-up">
      <h3 className="text-lg font-semibold text-secondary-900 mb-6">
        📡 {t("dashboard.liveActivity")}
      </h3>

      <div className="space-y-3 max-h-80 overflow-y-auto">
        <div className="text-center py-8">
          <p className="text-sm text-secondary-500">
            {t("dashboard.liveActivity")} - {t("common.noData")}
          </p>
        </div>
      </div>
    </div>
  );
};

// Network Statistics Component
const NetworkStats: React.FC = () => {
  const { state } = useStatus();
  const { t } = useI18n();

  const formatBytes = (bytes: number) => {
    if (bytes === 0) return "0 B";
    const k = 1024;
    const sizes = ["B", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + " " + sizes[i];
  };

  // Use real network data from state if available
  const networkData = {
    bytesIn: 0,
    bytesOut: 0,
    packetsIn: 0,
    packetsOut: 0,
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6 dashboard-slide-up">
      <h3 className="text-lg font-semibold text-secondary-900 mb-6">
        🌐 {t("dashboard.networkStats")}
      </h3>

      <div className="grid grid-cols-2 gap-4">
        <div className="text-center p-4 bg-blue-50 rounded-lg">
          <p className="text-2xl font-bold text-blue-600">
            {formatBytes(networkData.bytesIn)}
          </p>
          <p className="text-sm text-blue-700">{t("dashboard.incomingTraffic")}</p>
          <p className="text-xs text-blue-500 mt-1">
            {networkData.packetsIn} {t("dashboard.packets")}
          </p>
        </div>
        <div className="text-center p-4 bg-green-50 rounded-lg">
          <p className="text-2xl font-bold text-green-600">
            {formatBytes(networkData.bytesOut)}
          </p>
          <p className="text-sm text-green-700">{t("dashboard.outgoingTraffic")}</p>
          <p className="text-xs text-green-500 mt-1">
            {networkData.packetsOut} {t("dashboard.packets")}
          </p>
        </div>
      </div>

      <div className="mt-4 pt-4 border-t border-secondary-200">
        <div className="flex justify-between text-xs text-secondary-500">
          <span>
            {t("dashboard.activeConnections")}:{" "}
            {
              state.clients.filter((c) => c.connection_status === "connected")
                .length
            }
          </span>
          <span>{t("dashboard.totalClients")}: {state.clients.length}</span>
        </div>
      </div>
    </div>
  );
};

// Performance Metrics Component
const PerformanceMetrics: React.FC = () => {
  const { state } = useStatus();
  const { t } = useI18n();

  // Use real performance data from state
  const metrics = {
    responseTime: state.metrics?.hub?.average_response_time || 0,
    throughput: state.metrics?.hub?.tasks_per_second || 0,
    errorRate: state.metrics?.hub?.error_rate || 0,
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6 dashboard-slide-up">
      <h3 className="text-lg font-semibold text-secondary-900 mb-6">
        ⚡ {t("dashboard.performanceMetrics")}
      </h3>

      <div className="space-y-4">
        <div className="flex justify-between items-center">
          <span className="text-sm text-secondary-600">{t("dashboard.responseTime")}</span>
          <span className="text-lg font-bold text-blue-600">
            {Math.round(metrics.responseTime)}ms
          </span>
        </div>

        <div className="flex justify-between items-center">
          <span className="text-sm text-secondary-600">
            {t("dashboard.throughput")}
          </span>
          <span className="text-lg font-bold text-green-600">
            {Math.round(metrics.throughput)} req/s
          </span>
        </div>

        <div className="flex justify-between items-center">
          <span className="text-sm text-secondary-600">{t("dashboard.errorRate")}</span>
          <span
            className={`text-lg font-bold ${metrics.errorRate > 2 ? "text-red-600" : "text-green-600"}`}
          >
            {metrics.errorRate.toFixed(1)}%
          </span>
        </div>

        {state.health?.uptime && (
          <div className="pt-4 border-t border-secondary-200">
            <div className="flex justify-between items-center">
              <span className="text-sm text-secondary-600">{t("dashboard.systemUptime")}</span>
              <span className="text-lg font-bold text-purple-600">
                {Math.floor(state.health.uptime / 3600)}h{" "}
                {Math.floor((state.health.uptime % 3600) / 60)}m
              </span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export const Dashboard: React.FC = () => {
  const { state } = useStatus();
  const { t } = useI18n();

  // Calculate quick stats
  const totalClients = state.clients.length;
  const connectedClients = state.clients.filter(
    (c) => c.connection_status === "connected",
  ).length;
  const connectionRate =
    totalClients > 0 ? (connectedClients / totalClients) * 100 : 0;
  const avgCpuUsage = state.metrics?.system?.cpu_usage || 0;
  const avgMemoryUsage = state.metrics?.system?.memory_usage || 0;

  return (
    <div className="space-y-8">
      {/* Page Header */}
      <div className="text-center mb-8">
        <h1 className="text-3xl font-bold text-gradient mb-2">
          🏠 {t("dashboard.title")} TetraCore
        </h1>
        <p className="text-lg text-secondary-600">
          {t("dashboard.subtitle")}
        </p>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <QuickStat
          title={t("dashboard.activeConnections")}
          value={connectedClients}
          subtitle={`${t("common.of")} ${totalClients} ${t("dashboard.totalClients").toLowerCase()}`}
          icon="👥"
          trend={{
            value: `${connectionRate.toFixed(0)}% ${t("common.online").toLowerCase()}`,
            isPositive: connectionRate > 50,
          }}
          color="blue"
        />

        <QuickStat
          title={t("dashboard.cpuUsage")}
          value={`${Math.round(avgCpuUsage)}%`}
          subtitle={t("dashboard.averageUsage")}
          icon="🖥️"
          trend={{
            value: avgCpuUsage > 70 ? t("dashboard.high") : t("dashboard.normal"),
            isPositive: avgCpuUsage <= 70,
          }}
          color={avgCpuUsage > 70 ? "red" : "green"}
        />

        <QuickStat
          title={t("dashboard.memoryUsage")}
          value={`${Math.round(avgMemoryUsage)}%`}
          subtitle={t("dashboard.ramMemory")}
          icon="💾"
          trend={{
            value: avgMemoryUsage > 80 ? t("dashboard.critical") : t("dashboard.stable"),
            isPositive: avgMemoryUsage <= 80,
          }}
          color={avgMemoryUsage > 80 ? "red" : "green"}
        />

        <QuickStat
          title={t("dashboard.systemHealth")}
          value={state.health?.status === "healthy" ? t("dashboard.healthy") : t("dashboard.issues")}
          subtitle={t("dashboard.overallStatus")}
          icon="❤️"
          color={state.health?.status === "healthy" ? "green" : "red"}
        />
      </div>

      {/* Main Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Left Column */}
        <div className="space-y-6">
          <SystemHealth />
          <ClientStatus clients={state.clients} />
        </div>

        {/* Right Column */}
        <div className="space-y-6">
          <LiveActivityFeed />
          <PerformanceMetrics />
        </div>
      </div>

      {/* Bottom Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <NetworkStats />

        {/* Alerts Panel */}
        <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6">
          <h3 className="text-lg font-semibold text-secondary-900 mb-6">
            🚨 {t("dashboard.systemAlerts")}
          </h3>

          {state.alerts.length > 0 ? (
            <div className="space-y-3">
              {state.alerts.slice(0, 4).map((alert, index) => (
                <div
                  key={alert.id}
                  className={`p-3 rounded-lg border-l-4 ${
                    alert.type === "error"
                      ? "bg-red-50 border-red-500"
                      : alert.type === "warning"
                        ? "bg-yellow-50 border-yellow-500"
                        : "bg-blue-50 border-blue-500"
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <div className="flex-1">
                      <p className="text-sm font-medium text-secondary-900">
                        {alert.title}
                      </p>
                      <p className="text-xs text-secondary-600 mt-1">
                        {alert.message}
                      </p>
                    </div>
                    <span className="text-xs text-secondary-500">
                      {new Date(alert.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-8">
              <p className="text-sm text-secondary-500">
                ✅ {t("alerts.noActiveAlerts")}
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};
